<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048</title>
<style>
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
body {
  background: #1a1a2e;
  color: #eee;
  font-family: Arial, sans-serif;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}
h1 {
  font-size: 3rem;
  margin-bottom: 10px;
  color: #e94560;
}
#score {
  font-size: 1.5rem;
  margin-bottom: 15px;
}
#board {
  display: grid;
  grid-template-columns: repeat(4, 80px);
  grid-template-rows: repeat(4, 80px);
  gap: 8px;
  background: #16213e;
  padding: 10px;
  border-radius: 8px;
}
.cell {
  width: 80px;
  height: 80px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: bold;
  border-radius: 6px;
  background: #0f3460;
  color: #eee;
  transition: background 0.1s;
}
.cell[data-value="2"] { background: #e94560; color: #fff; }
.cell[data-value="4"] { background: #f5a623; color: #fff; }
.cell[data-value="8"] { background: #f7c948; color: #333; }
.cell[data-value="16"] { background: #48bb78; color: #fff; }
.cell[data-value="32"] { background: #38b2ac; color: #fff; }
.cell[data-value="64"] { background: #4299e1; color: #fff; }
.cell[data-value="128"] { background: #667eea; color: #fff; font-size: 1.3rem; }
.cell[data-value="256"] { background: #764ba2; color: #fff; font-size: 1.3rem; }
.cell[data-value="512"] { background: #ed64a6; color: #fff; font-size: 1.3rem; }
.cell[data-value="1024"] { background: #fc8181; color: #fff; font-size: 1.1rem; }
.cell[data-value="2048"] { background: #ffd700; color: #333; font-size: 1.1rem; }
#reset {
  margin-top: 20px;
  padding: 10px 30px;
  font-size: 1.1rem;
  background: #e94560;
  color: #fff;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}
#reset:hover {
  background: #c73650;
}
</style>
</head>
<body>
<h1>2048</h1>
<div id="score">Score: 0</div>
<div id="board"></div>
<button id="reset">New Game</button>

<script>
(function() {
  const SIZE = 4;
  let grid = [];
  let currentScore = 0;

  function createEmptyGrid() {
    return Array.from({length: SIZE}, () => Array(SIZE).fill(0));
  }

  function cloneGrid(g) {
    return g.map(row => [...row]);
  }

  function getEmptyCells(g) {
    const cells = [];
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (g[r][c] === 0) cells.push([r, c]);
    return cells;
  }

  function spawnTile(g) {
    const empty = getEmptyCells(g);
    if (empty.length === 0) return false;
    const [r, c] = empty[Math.floor(Math.random() * empty.length)];
    g[r][c] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  function slideLine(line) {
    // Remove zeros
    let filtered = line.filter(v => v !== 0);
    let merged = [];
    let scoreGain = 0;
    let i = 0;
    while (i < filtered.length) {
      if (i + 1 < filtered.length && filtered[i] === filtered[i + 1]) {
        const val = filtered[i] * 2;
        merged.push(val);
        scoreGain += val;
        i += 2;
      } else {
        merged.push(filtered[i]);
        i++;
      }
    }
    // Pad with zeros
    while (merged.length < SIZE) merged.push(0);
    return { line: merged, scoreGain };
  }

  function moveLeft(g) {
    let scoreGain = 0;
    const newGrid = createEmptyGrid();
    for (let r = 0; r < SIZE; r++) {
      const result = slideLine(g[r]);
      newGrid[r] = result.line;
      scoreGain += result.scoreGain;
    }
    return { grid: newGrid, scoreGain };
  }

  function moveRight(g) {
    let scoreGain = 0;
    const newGrid = createEmptyGrid();
    for (let r = 0; r < SIZE; r++) {
      const reversed = [...g[r]].reverse();
      const result = slideLine(reversed);
      newGrid[r] = result.line.reverse();
      scoreGain += result.scoreGain;
    }
    return { grid: newGrid, scoreGain };
  }

  function moveUp(g) {
    let scoreGain = 0;
    const newGrid = createEmptyGrid();
    for (let c = 0; c < SIZE; c++) {
      const col = [];
      for (let r = 0; r < SIZE; r++) col.push(g[r][c]);
      const result = slideLine(col);
      for (let r = 0; r < SIZE; r++) newGrid[r][c] = result.line[r];
      scoreGain += result.scoreGain;
    }
    return { grid: newGrid, scoreGain };
  }

  function moveDown(g) {
    let scoreGain = 0;
    const newGrid = createEmptyGrid();
    for (let c = 0; c < SIZE; c++) {
      const col = [];
      for (let r = 0; r < SIZE; r++) col.push(g[r][c]);
      col.reverse();
      const result = slideLine(col);
      const line = result.line.reverse();
      for (let r = 0; r < SIZE; r++) newGrid[r][c] = line[r];
      scoreGain += result.scoreGain;
    }
    return { grid: newGrid, scoreGain };
  }

  function gridsEqual(a, b) {
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (a[r][c] !== b[r][c]) return false;
    return true;
  }

  function render() {
    const boardEl = document.getElementById('board');
    boardEl.innerHTML = '';
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const cell = document.createElement('div');
        cell.className = 'cell';
        const val = grid[r][c];
        if (val !== 0) {
          cell.textContent = val;
          cell.setAttribute('data-value', val);
        }
        boardEl.appendChild(cell);
      }
    }
    document.getElementById('score').textContent = 'Score: ' + currentScore;
  }

  function resetGame() {
    grid = createEmptyGrid();
    currentScore = 0;
    spawnTile(grid);
    spawnTile(grid);
    render();
  }

  function doMove(direction) {
    const oldGrid = cloneGrid(grid);
    let result;
    switch (direction) {
      case 'left': result = moveLeft(grid); break;
      case 'right': result = moveRight(grid); break;
      case 'up': result = moveUp(grid); break;
      case 'down': result = moveDown(grid); break;
      default: return false;
    }
    const changed = !gridsEqual(oldGrid, result.grid);
    if (changed) {
      grid = result.grid;
      currentScore += result.scoreGain;
      spawnTile(grid);
      render();
    }
    return changed;
  }

  // Expose API
  window.game = {
    size: SIZE,
    reset: resetGame,
    move: function(dir) { return doMove(dir); },
    board: function() { return cloneGrid(grid); },
    setBoard: function(arr) {
      grid = arr.map(row => [...row]);
      render();
    },
    score: function() { return currentScore; }
  };

  // Keyboard controls
  document.addEventListener('keydown', function(e) {
    const keyMap = {
      'ArrowLeft': 'left',
      'ArrowRight': 'right',
      'ArrowUp': 'up',
      'ArrowDown': 'down'
    };
    if (keyMap[e.key]) {
      e.preventDefault();
      doMove(keyMap[e.key]);
    }
  });

  // Reset button
  document.getElementById('reset').addEventListener('click', resetGame);

  // Start game
  resetGame();
})();
</script>
</body>
</html>
